import { ACHIEVEMENTS } from 'data:application/javascript;base64,';

export class UIPanels {
    constructor(game) {
        this.game = game;
        this.isPanelMinimized = false;
        this.isRadioMinimized = false;
    }

    setupPanelToggle() {
        const panelToggle = document.getElementById('panel-toggle');
        const uiPanel = document.getElementById('ui-panel');
        
        if (panelToggle && uiPanel) {
            const newPanelToggle = panelToggle.cloneNode(true);
            panelToggle.parentNode.replaceChild(newPanelToggle, panelToggle);

            newPanelToggle.addEventListener('click', () => {
                this.isPanelMinimized = !this.isPanelMinimized;
                uiPanel.classList.toggle('minimized');
                const toggleIcon = newPanelToggle.querySelector('span');
                if (toggleIcon) {
                    toggleIcon.textContent = this.isPanelMinimized ? '+' : '-';
                }
            });
        }

        // Setup radio toggle
        const radioToggle = document.getElementById('radio-toggle-header');
        const radioInfo = document.getElementById('radio-info');
        
        if (radioToggle && radioInfo) {
            const newRadioToggle = radioToggle.cloneNode(true);
            radioToggle.parentNode.replaceChild(newRadioToggle, radioToggle);

            newRadioToggle.addEventListener('click', () => {
                this.isRadioMinimized = !this.isRadioMinimized;
                radioInfo.classList.toggle('minimized');
                const toggleIcon = newRadioToggle.querySelector('span');
                if (toggleIcon) {
                    toggleIcon.textContent = this.isRadioMinimized ? '+' : '-';
                }
            });
        }
    }

    setupControlsToggle() {
        const joystickToggle = document.getElementById('joystick-toggle');
        if (joystickToggle) {
            joystickToggle.checked = this.game.ui.joystickEnabled;
            joystickToggle.addEventListener('change', (e) => {
                this.game.ui.joystickEnabled = e.target.checked;
                this.game.toggleJoystick(this.game.ui.joystickEnabled);
            });
        }
    }

    setupAchievementsPanel() {
        const panel = document.getElementById('achievements-panel');
        const openBtn = document.getElementById('achievements-btn');
        const closeBtn = document.getElementById('close-achievements-btn');

        if (!panel || !openBtn || !closeBtn) return;

        const newOpenBtn = openBtn.cloneNode(true);
        openBtn.parentNode.replaceChild(newOpenBtn, openBtn);
        const newCloseBtn = closeBtn.cloneNode(true);
        closeBtn.parentNode.replaceChild(newCloseBtn, closeBtn);

        newOpenBtn.addEventListener('click', () => {
            this.updateAchievementsUI(this.game.state.achievementsUnlocked);
            panel.classList.remove('hidden');
        });

        newCloseBtn.addEventListener('click', () => {
            panel.classList.add('hidden');
        });
    }

    setupResetButton() {
        const resetButton = document.getElementById('reset-progress-btn');
        if (resetButton) {
            const newResetButton = resetButton.cloneNode(true);
            resetButton.parentNode.replaceChild(newResetButton, resetButton);

            newResetButton.addEventListener('click', () => this.game.resetProgress());
        }
    }

    updateAchievementsUI(unlockedAchievements) {
        const listContainer = document.getElementById('achievements-list');
        if (!listContainer) return;
        listContainer.innerHTML = '';

        for (const id in ACHIEVEMENTS) {
            const achievement = ACHIEVEMENTS[id];
            const isUnlocked = unlockedAchievements.includes(id);

            let rewardText = '';
            if (achievement.reward) {
                const rewards = [];
                if (achievement.reward.xp) rewards.push(`${achievement.reward.xp} XP`);
                if (achievement.reward.money) rewards.push(`$${achievement.reward.money.toLocaleString()}`);
                rewardText = rewards.join(' + ');
            }

            const achievementEl = document.createElement('div');
            achievementEl.className = `achievement-item ${isUnlocked ? 'unlocked' : ''}`;
            achievementEl.innerHTML = `
                <h4>${achievement.name} ${isUnlocked ? '✔️' : ''}</h4>
                <p>${achievement.description}</p>
                <div class="reward">Reward: ${rewardText}</div>
            `;
            listContainer.appendChild(achievementEl);
        }
    }
}